import { Platform } from 'react-native';
import { ImageStorageRepository } from './ImageStorageRepository';
import { ENV } from '../config/env';

/**
 * ImageKit implementation of the ImageStorageRepository interface.
 * Implements a secure client-side upload workflow using authorization signatures
 * generated by our serverless Vercel backend to avoid exposing the private API key.
 */
export class ImageKitStorageRepository implements ImageStorageRepository {
  async uploadFile(localPath: string, destinationFolder: string): Promise<string> {
    // Basic verification of environment settings
    if (!ENV.IMAGEKIT_PUBLIC_KEY || ENV.IMAGEKIT_PUBLIC_KEY === 'YOUR_IMAGEKIT_PUBLIC_KEY_PLACEHOLDER') {
      throw new Error('ImageKit public key is not configured in env.ts. Please update your environment variables.');
    }
    if (!ENV.VERCEL_API_URL || ENV.VERCEL_API_URL === 'YOUR_VERCEL_BACKEND_URL_PLACEHOLDER') {
      throw new Error('Vercel API base URL is not configured in env.ts. Please deploy your backend and set the URL.');
    }

    try {
      // 1. Retrieve the signature, token, and expiry details from Vercel backend.
      const authEndpoint = `${ENV.VERCEL_API_URL}/api/imagekit-auth`;
      const authResponse = await fetch(authEndpoint);
      
      if (!authResponse.ok) {
        throw new Error(
          `Failed to retrieve upload signature from Vercel. Status: ${authResponse.status} ${authResponse.statusText}`
        );
      }
      
      const authData = await authResponse.json();
      const { signature, token, expire } = authData;

      if (!signature || !token || !expire) {
        throw new Error('Invalid signature payload received from backend.');
      }

      // 2. Format the file name and mime type for multi-part boundary upload
      const fileName = localPath.split('/').pop() || `upload_${Date.now()}.jpg`;
      let mimeType = 'image/jpeg';
      if (fileName.toLowerCase().endsWith('.png')) {
        mimeType = 'image/png';
      } else if (fileName.toLowerCase().endsWith('.webp')) {
        mimeType = 'image/webp';
      } else if (fileName.toLowerCase().endsWith('.gif')) {
        mimeType = 'image/gif';
      }

      // 3. Construct the multipart Form Data
      const formData = new FormData();
      
      // Ensure file path format is correct across iOS and Android
      const formattedUri = Platform.OS === 'android' ? localPath : localPath.replace('file://', '');
      
      formData.append('file', {
        uri: formattedUri,
        name: fileName,
        type: mimeType,
      } as any);
      formData.append('fileName', fileName);
      formData.append('publicKey', ENV.IMAGEKIT_PUBLIC_KEY);
      formData.append('signature', signature);
      formData.append('token', token);
      formData.append('expire', String(expire));
      formData.append('folder', `/${destinationFolder}`);

      // 4. Dispatch the multipart upload request directly to ImageKit's API endpoints
      const uploadResponse = await fetch('https://upload.imagekit.io/api/v1/files/upload', {
        method: 'POST',
        body: formData,
        headers: {
          'Content-Type': 'multipart/form-data',
        },
      });

      if (!uploadResponse.ok) {
        const errorText = await uploadResponse.text();
        throw new Error(`ImageKit API rejected the upload. Details: ${errorText}`);
      }

      const uploadResult = await uploadResponse.json();
      
      if (!uploadResult.url) {
        throw new Error('ImageKit upload did not return a valid media URL.');
      }

      // Return the direct HTTPS URL to be stored in the database
      return uploadResult.url;
    } catch (error) {
      console.error('[ImageKitStorageRepository] Upload failed:', error);
      throw error;
    }
  }
}
